INSERT INTO `_1kycore_level_guard` SELECT 1 FROM `gameobject_template` a JOIN `_1kycore_level_templates` n ON a.`entry`=n.`entry` WHERE NOT (a.`type` <=> n.`type` AND a.`displayId` <=> n.`displayId` AND BINARY a.`name` <=> BINARY n.`name` AND BINARY a.`IconName` <=> BINARY n.`IconName` AND BINARY a.`castBarCaption` <=> BINARY n.`castBarCaption` AND BINARY a.`unk1` <=> BINARY n.`unk1` AND ABS(a.`size`-n.`size`)<=0.000001 AND a.`Data0` <=> n.`Data0` AND a.`Data1` <=> n.`Data1` AND a.`Data2` <=> n.`Data2` AND a.`Data3` <=> n.`Data3` AND a.`Data4` <=> n.`Data4` AND a.`Data5` <=> n.`Data5` AND a.`Data6` <=> n.`Data6` AND a.`Data7` <=> n.`Data7` AND a.`Data8` <=> n.`Data8` AND a.`Data9` <=> n.`Data9` AND a.`Data10` <=> n.`Data10` AND a.`Data11` <=> n.`Data11` AND a.`Data12` <=> n.`Data12` AND a.`Data13` <=> n.`Data13` AND a.`Data14` <=> n.`Data14` AND a.`Data15` <=> n.`Data15` AND a.`Data16` <=> n.`Data16` AND a.`Data17` <=> n.`Data17` AND a.`Data18` <=> n.`Data18` AND a.`Data19` <=> n.`Data19` AND a.`Data20` <=> n.`Data20` AND a.`Data21` <=> n.`Data21` AND a.`Data22` <=> n.`Data22` AND a.`Data23` <=> n.`Data23` AND a.`Data24` <=> n.`Data24` AND a.`Data25` <=> n.`Data25` AND a.`Data26` <=> n.`Data26` AND a.`Data27` <=> n.`Data27` AND a.`Data28` <=> n.`Data28` AND a.`Data29` <=> n.`Data29` AND a.`Data30` <=> n.`Data30` AND a.`Data31` <=> n.`Data31` AND a.`Data32` <=> n.`Data32` AND a.`RequiredLevel` <=> n.`RequiredLevel` AND BINARY a.`AIName` <=> BINARY n.`AIName` AND BINARY a.`ScriptName` <=> BINARY n.`ScriptName`) LIMIT 1;
